<?php

namespace App\Controllers\Api\V1\Admin;

use App\Controllers\Api\V1\BaseApiController;
use CodeIgniter\HTTP\ResponseInterface;

/**
 * SeoController
 *
 * Staff console endpoints for inspecting SEO, AEO, AIO, and GEO performance,
 * viewing prioritized optimization recommendations, and streaming the standalone
 * interactive dashboard generated by the Unified Website Optimization Engine (UWOE).
 */
class SeoController extends BaseApiController
{
    private string $engineDir;

    public function __construct(?string $engineDir = null)
    {
        $this->engineDir = $engineDir
            ?? (getenv('UWOE_DIR') ?: (realpath(ROOTPATH . '../../Optimization engine') ?: (ROOTPATH . '../../Optimization engine')));
    }

    private function engineRequest(string $method, string $path, ?array $body = null): ?array
    {
        $base = rtrim((string) getenv('SEO_SERVICE_URL'), '/');
        $key = (string) getenv('SEO_AUDIT_KEY');
        if ($base === '' || $key === '') {
            return null;
        }
        $headers = "x-seo-key: {$key}\r\nAccept: application/json\r\n";
        if ($body !== null) {
            $headers .= "Content-Type: application/json\r\n";
        }
        $context = stream_context_create(['http' => [
            'method' => $method,
            'header' => $headers,
            'content' => $body === null ? '' : json_encode($body),
            'timeout' => 4,
            'ignore_errors' => true,
        ]]);
        $raw = @file_get_contents($base . $path, false, $context);
        if ($raw === false) return null;
        preg_match('/HTTP\/\S+\s+(\d+)/', $http_response_header[0] ?? '', $match);
        return ['status' => (int) ($match[1] ?? 0), 'body' => json_decode($raw, true) ?: []];
    }

    /**
     * Locate the latest report.json file
     */
    private function getLatestReport(): ?array
    {
        $uwoeDir = $this->engineDir . DIRECTORY_SEPARATOR . '.uwoe';
        if (! is_dir($uwoeDir)) {
            return null;
        }

        $dirs = scandir($uwoeDir);
        foreach ($dirs as $d) {
            if ($d === '.' || $d === '..') {
                continue;
            }
            $reportFile = $uwoeDir . DIRECTORY_SEPARATOR . $d . DIRECTORY_SEPARATOR . 'out' . DIRECTORY_SEPARATOR . 'report.json';
            if (is_file($reportFile)) {
                $content = @file_get_contents($reportFile);
                if ($content !== false) {
                    $json = json_decode($content, true);
                    if (is_array($json)) {
                        return $json;
                    }
                }
            }
        }
        return null;
    }

    /**
     * Locate the latest dashboard.html path
     */
    private function getLatestDashboardPath(): ?string
    {
        $uwoeDir = $this->engineDir . DIRECTORY_SEPARATOR . '.uwoe';
        if (! is_dir($uwoeDir)) {
            return null;
        }

        $dirs = scandir($uwoeDir);
        foreach ($dirs as $d) {
            if ($d === '.' || $d === '..') {
                continue;
            }
            $dashFile = $uwoeDir . DIRECTORY_SEPARATOR . $d . DIRECTORY_SEPARATOR . 'out' . DIRECTORY_SEPARATOR . 'dashboard.html';
            if (is_file($dashFile)) {
                return $dashFile;
            }
        }
        return null;
    }

    /**
     * GET /api/v1/admin/seo/status
     */
    public function status(): ResponseInterface
    {
        $report = $this->getLatestReport();
        $engine = $this->engineRequest('GET', '/status');
        $recs = $report['analysis']['recommendations'] ?? [];

        $criticalCount = 0;
        $highCount = 0;
        $mediumCount = 0;
        $lowCount = 0;

        foreach ($recs as $r) {
            $sev = strtolower((string) ($r['severity'] ?? ''));
            if ($sev === 'critical') $criticalCount++;
            elseif ($sev === 'high') $highCount++;
            elseif ($sev === 'medium') $mediumCount++;
            elseif ($sev === 'low') $lowCount++;
        }

        // No fabricated scores. When no real UWOE report exists, every metric is
        // null and is_configured is false — the console renders an honest "no
        // audit has been run" state rather than canned 93/100 numbers.
        $hasReport = $report !== null;

        return $this->response->setJSON([
            'status' => 200,
            'data'   => [
                'is_auditing'   => (bool) ($engine['body']['running'] ?? false),
                'engine_available' => ($engine['status'] ?? 0) === 200,
                'last_error' => $engine['body']['last_error'] ?? null,
                'monitoring' => $engine['body']['monitoring'] ?? null,
                'platform_syncing' => (bool) ($engine['body']['platform_syncing'] ?? false),
                'google' => $engine['body']['google'] ?? ['configured' => false, 'connected' => false],
                'analytics' => $engine['body']['analytics'] ?? ['configured' => false, 'connected' => false],
                'bing' => $engine['body']['bing'] ?? ['configured' => false, 'connected' => false],
                'is_configured' => $hasReport,
                'last_audit_at' => $report['meta']['generatedAt'] ?? null,
                'target_url'    => $report['meta']['site'] ?? 'https://tenderhub.lk',
                'scores'        => $report['analysis']['scores'] ?? null,
                'crawl_stats'   => $report['observed']['crawl']['stats'] ?? null,
                'summary'       => $hasReport ? [
                    'capabilities_present'  => count($report['observed']['inventory']['present'] ?? []),
                    'conflicts'             => count($report['observed']['inventory']['conflicts'] ?? []),
                    'recommendations_count' => count($recs),
                    'critical_count'        => $criticalCount,
                    'high_count'            => $highCount,
                    'medium_count'          => $mediumCount,
                    'low_count'             => $lowCount,
                ] : null,
                'disclaimer'    => $hasReport
                    ? ($report['meta']['scoreDisclaimer'] ?? 'Scores measure how many of this platform\'s technical and content checks the site currently passes.')
                    : 'No SEO audit report is available yet. Run the Unified Website Optimization Engine to generate one.',
            ],
            'meta'   => [
                'now' => date('c'),
            ],
        ]);
    }

    private function indexNowConfig(): array
    {
        $path = WRITEPATH . 'sources_config.json';
        $all = is_file($path) ? (json_decode((string) file_get_contents($path), true) ?: []) : [];
        return array_replace(['enabled' => false, 'hour' => 4, 'max_urls' => 500, 'batch_size' => 1000, 'delay_ms' => 150, 'max_load_ratio' => .80, 'max_memory_ratio' => .80], is_array($all['indexnow'] ?? null) ? $all['indexnow'] : []);
    }

    private function saveIndexNowConfig(array $value): void
    {
        $path = WRITEPATH . 'sources_config.json';
        $all = is_file($path) ? (json_decode((string) file_get_contents($path), true) ?: []) : [];
        $all['indexnow'] = $value;
        $tmp = $path . '.tmp';
        if (file_put_contents($tmp, json_encode($all, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES), LOCK_EX) === false || ! rename($tmp, $path)) throw new \RuntimeException('Unable to persist IndexNow configuration.');
        @chmod($path, 0600);
    }

    public function indexNow(): ResponseInterface
    {
        $db = db_connect();
        return $this->response->setJSON(['status' => 200, 'data' => [
            'config' => $this->indexNowConfig(),
            'recent_runs' => $db->table('indexnow_runs')->orderBy('id', 'DESC')->limit(10)->get()->getResultArray(),
        ]]);
    }

    public function updateIndexNow(): ResponseInterface
    {
        $body = $this->body();
        $current = $this->indexNowConfig();
        $next = [
            'enabled' => filter_var($body['enabled'] ?? $current['enabled'], FILTER_VALIDATE_BOOLEAN),
            'hour' => max(0, min(23, (int) ($body['hour'] ?? $current['hour']))),
            'max_urls' => max(1, min(5000, (int) ($body['max_urls'] ?? $current['max_urls']))),
            'batch_size' => max(1, min(1000, (int) ($body['batch_size'] ?? $current['batch_size']))),
            'delay_ms' => max(50, min(5000, (int) ($body['delay_ms'] ?? $current['delay_ms']))),
            'max_load_ratio' => max(.20, min(.95, (float) ($body['max_load_ratio'] ?? $current['max_load_ratio']))),
            'max_memory_ratio' => max(.20, min(.95, (float) ($body['max_memory_ratio'] ?? $current['max_memory_ratio']))),
        ];
        $this->saveIndexNowConfig($next);
        service('eventLedger')->record('source', 0, 'seo.indexnow_updated', 'IndexNow automation configuration updated.', $next);
        return $this->response->setJSON(['status' => 200, 'data' => $next]);
    }

    /**
     * POST /api/v1/admin/seo/platforms/sync
     */
    public function syncPlatforms(): ResponseInterface
    {
        $result = $this->engineRequest('POST', '/platforms/sync');
        if ($result === null) {
            return $this->response->setStatusCode(503)->setJSON([
                'status' => 503,
                'message' => 'The SEO service is unavailable.',
            ]);
        }

        return $this->response->setStatusCode($result['status'])->setJSON([
            'status' => $result['status'],
            'data' => $result['body'],
        ]);
    }

    /**
     * POST /api/v1/admin/seo/audit
     */
    public function audit(): ResponseInterface
    {
        $body = $this->request->getJSON(true) ?? $this->request->getPost();
        $target = $body['targetUrl'] ?? 'https://tenderhub.lk';
        $maxPages = max(1, min((int) ($body['maxPages'] ?? 20), 200));

        if ($target !== 'https://tenderhub.lk') {
            return problem(422, 'invalid_target', 'Audits are restricted to https://tenderhub.lk.');
        }
        $result = $this->engineRequest('POST', '/audit', ['targetUrl' => $target, 'maxPages' => $maxPages]);
        if (($result['status'] ?? 0) === 202) {
            return $this->response->setStatusCode(202)->setJSON([
                'status' => 202,
                'data' => ['is_auditing' => true, 'target_url' => $target, 'max_pages' => $maxPages],
            ]);
        }
        if (($result['status'] ?? 0) === 409) {
            return problem(409, 'audit_running', 'An SEO audit is already running.');
        }

        // Honest boundary. The Unified Website Optimization Engine is a separate
        // Node project ("Optimization engine/") that is NOT part of the API
        // runtime/image, so this endpoint cannot actually start an audit — the
        // previous version returned status:"running" while doing nothing, and the
        // console then reported "audit completed successfully". Report the real
        // situation instead and point at how to produce a report.
        return $this->response->setStatusCode(503)->setJSON([
            'status'  => 503,
            'reason'  => 'engine_not_available',
            'detail'  => 'The SEO audit service is unavailable or refused the request. Check its container and configuration.',
            'data'    => [
                'target_url' => $target,
                'max_pages'  => $maxPages,
                'status'     => 'unavailable',
            ],
        ]);
    }

    /**
     * GET /api/v1/admin/seo/recommendations
     */
    public function recommendations(): ResponseInterface
    {
        $report = $this->getLatestReport();
        $recs = $report['analysis']['recommendations'] ?? [];

        return $this->response->setJSON([
            'status' => 200,
            'data'   => $recs,
            'meta'   => [
                'total' => count($recs),
                'now'   => date('c'),
            ],
        ]);
    }

    /**
     * GET /api/v1/admin/seo/dashboard
     */
    public function dashboard()
    {
        $dashPath = $this->getLatestDashboardPath();
        if ($dashPath && is_file($dashPath)) {
            return $this->response
                ->setHeader('Content-Type', 'text/html; charset=utf-8')
                ->setBody(file_get_contents($dashPath));
        }

        return $this->response
            ->setStatusCode(404)
            ->setHeader('Content-Type', 'text/html; charset=utf-8')
            ->setBody('<html><body><h2>No dashboard found. Please run an audit first.</h2></body></html>');
    }

    /**
     * GET /api/v1/admin/seo/report
     */
    public function report(): ResponseInterface
    {
        $report = $this->getLatestReport();
        if ($report) {
            return $this->response->setJSON(['status' => 200, 'data' => $report]);
        }

        return $this->response->setStatusCode(404)->setJSON(['status' => 404, 'detail' => 'Report not found.']);
    }
}
